// Builds machine-readable test fixtures from the prompt set and the creative director samples.
// Usage: node current/tests/fixtures/build-fixtures.mjs
// Writes: fixtures/prompts.json, fixtures/operational-chunks.json
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const FIX = dirname(fileURLToPath(import.meta.url));
const TESTS = join(FIX, "..");
const CD = join(TESTS, "creative-director");

// 1. Prompt set (prompt-set/video-prompts.md) → prompts.json
function parsePromptSet(md) {
  const groups = [];
  let group = null, prompt = null, field = null;
  for (const line of md.split("\n")) {
    let m;
    if ((m = line.match(/^## (\d+)\. (.+)$/))) {
      group = { number: Number(m[1]), name: m[2].trim(), tests: "", edge_cases: [], subsystems: "", prompts: [] };
      groups.push(group); prompt = null; field = null; continue;
    }
    if (!group) continue;
    if ((m = line.match(/^- \*\*Tests:\*\* (.+)$/))) { group.tests = m[1].trim(); field = null; continue; }
    if (/^- \*\*Edge-case challenges:\*\*/.test(line)) { field = "edge"; continue; }
    if ((m = line.match(/^- \*\*Subsystems stressed:\*\* (.+)$/))) { group.subsystems = m[1].trim(); field = null; continue; }
    if ((m = line.match(/^- \*\*(\d+\.\d+)\*\* `([\w-]+)`(?:\s+—\s+(.+))?$/))) {
      prompt = { id: m[1], provenance: m[2], source: m[3]?.trim() ?? null, prompt: "", uploads: "", expected_handling: [] };
      group.prompts.push(prompt); field = null; continue;
    }
    if (field === "edge" && (m = line.match(/^  - (.+)$/))) { group.edge_cases.push(m[1].trim()); continue; }
    if (!prompt) continue;
    if ((m = line.match(/^  - Prompt: (.+)$/))) { prompt.prompt = m[1].trim().replace(/^"|"$/g, ""); field = null; continue; }
    if ((m = line.match(/^  - Uploads: (.+)$/))) { prompt.uploads = m[1].trim(); field = null; continue; }
    if (/^  - Expected handling:/.test(line)) { field = "expected"; continue; }
    if (field === "expected" && (m = line.match(/^    - (.+)$/))) { prompt.expected_handling.push(m[1].trim()); continue; }
  }
  return groups;
}

const groups = parsePromptSet(readFileSync(join(TESTS, "prompt-set", "video-prompts.md"), "utf8"));
const promptSet = groups.flatMap((g) => g.prompts.map((p) => ({
  set: "prompt-set", group: g.number, group_name: g.name, group_tests: g.tests, subsystems_stressed: g.subsystems, ...p,
})));

const requestSets = ["requests.json", "requests-logo.json"].flatMap((file) =>
  JSON.parse(readFileSync(join(CD, file), "utf8")).map((r) => ({ set: `creative-director/${file}`, ...r })));

writeFileSync(join(FIX, "prompts.json"), JSON.stringify({
  note: "Generated by build-fixtures.mjs. Source: prompt-set/video-prompts.md and creative-director/requests*.json.",
  prompt_set: { groups: groups.map(({ prompts, ...g }) => ({ ...g, prompt_ids: prompts.map((p) => p.id) })), prompts: promptSet },
  creative_director_requests: requestSets,
}, null, 2));

// 2. Operational chunks (creative director outputs) → operational-chunks.json
const FORMATS = [
  { step: "v3b", format: "A-straight", description: "Full state per chunk" },
  { step: "v5b", format: "B-change", description: "Baseline, then only the changes per chunk" },
];
const NOTES = { "claude/p4-lighthouse/v5b": "Edited by the agent: first draft totalled about 130 s, rescaled to 120 s." };
const rel = (p) => relative(TESTS, p);
const chunks = [];
for (const r of requestSets) {
  for (const model of ["gpt", "claude"]) {
    const dir = join(CD, "outputs", model, r.id);
    const story = join(dir, "v3a.md");
    if (!existsSync(story)) continue;
    for (const f of FORMATS) {
      const file = join(dir, `${f.step}.md`);
      if (!existsSync(file)) continue;
      chunks.push({
        request_id: r.id, request: r.request, uploads: r.uploads,
        model: model === "gpt" ? "gpt-6.1-sol" : "claude-opus-5.5",
        format: f.format, format_description: f.description,
        story_path: rel(story), chunks_path: rel(file),
        note: NOTES[`${model}/${r.id}/${f.step}`] ?? null,
      });
    }
  }
}
writeFileSync(join(FIX, "operational-chunks.json"), JSON.stringify({
  note: "Generated by build-fixtures.mjs. Inputs for state splitter tests. Paths are relative to current/tests/.",
  fixtures: chunks,
}, null, 2));

console.log(`prompts.json: ${promptSet.length} prompt-set prompts in ${groups.length} groups, ${requestSets.length} creative director requests`);
console.log(`operational-chunks.json: ${chunks.length} chunk fixtures`);
